#include<bits/stdc++.h>

using namespace std;

class DaySo{
	private:
		int n;
		int *a;
	public:
		DaySo(){
		    n = 0;
        	a = new int[50];
		}
	    int getN() { 
	        return n; 
	    }
		int* getA() {
		    return a;
		}
		friend istream& operator >> (istream &is, DaySo &ds) {
		    cout << "\nNhap so phan tu: ";
		    is >> ds.n;
		    while (ds.n < 0 || ds.n > 50) {
		        cout << "So phan tu khong hop le! Nhap lai: ";
		        is >> ds.n;
		    }
		    cout << endl;
		    for (int i = 0; i < ds.n; i++) {
		        cout << "Nhap he so cua phan tu " << i << ": ";
		        is >> ds.a[i];
		    }
		    cout << endl;
		    return is;
		}
		friend ostream& operator << (ostream &os, const DaySo &ds){
			os << "\n--Gia tri day so luu duoc--" << endl;
			for(int i = 0; i < ds.n; i++){
				os << "Phan tu " << i << ": ";
				os << ds.a[i] << endl;
			}
	        os << endl;
	        return os;
		}
	    // Tinh tong cac phan tu duong
	    int tongDuong() {
	        int tong = 0;
	        for (int i = 0; i < n; i++) {
	            if (a[i] > 0) {
	                tong += a[i];
	            }
	        }
	        return tong;
	    }
	    // Tim phan tu chan lon nhat
		int maxChan() {
		    int tmp;
		    bool coChan = false;
		    for (int i = 0; i < n; i++) {
		        if (a[i] % 2 == 0) {
		            if (!coChan || a[i] > tmp) {
		                tmp = a[i];
		            }
		            coChan = true;
		        }
		    }
		    if (!coChan) {
		        cout << "Day so khong co so chan!" << endl;
		        return 0;
		    }
		    return tmp;
		}
		void giaiPhong() {
		    delete[] a;
		    a = nullptr;
		    n = 0;
		}
};




int main(){
    DaySo A;
    cout << "=== NHAP DU LIEU DAY SO A ===" << endl;
    cin >> A;
    cout << "=== XUAT DU LIEU DAY SO A ===" << endl;
    cout << A;
    cout << "=== KET QUA TINH TOAN ===" << endl;
    cout << "Tong cac phan tu duong: " << A.tongDuong() << endl;
    int max_chan = A.maxChan();
    cout << "Phan tu chan lon nhat: " << max_chan << endl;
    // Giai phong bo nho
    A.giaiPhong();
    return 0;
}

